export const getRemoveFollowerUrl = (followerId: number) => {
  return `/api/userWallet/follower/${followerId}`;
};

/**
 * 将指定粉丝从当前登录用户的粉丝列表中移除（等价于该粉丝取关我）。幂等。
 * @summary 移除粉丝
 */
export const removeFollower = async (
  followerId: number,
  options?: RequestInit,
): Promise<removeFollowerResponse> => {
  return appAxiosInstance<removeFollowerResponse>(
    getRemoveFollowerUrl(followerId),
    {
      ...options,
      method: 'DELETE',
    },
  );
};

export const getRemoveFollowerMutationOptions = <
  TError = ResultObject,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof removeFollower>>,
    TError,
    { followerId: number },
    TContext
  >;
  request?: SecondParameter<typeof appAxiosInstance>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof removeFollower>>,
  TError,
  { followerId: number },
  TContext
> => {
  const mutationKey = ['removeFollower'];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      'mutationKey' in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof removeFollower>>,
    { followerId: number }
  > = (props) => {
    const { followerId } = props ?? {};

    return removeFollower(followerId, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

